-- Bunny Court content v2, sourced from Burrow_Bunny_Court_Content_System_v1 (5).xlsx.
-- Existing sessions retain their immutable v1 content_snapshot; new sessions use v2.
begin;

create table if not exists public.court_free_rule_branches (
  case_id text not null references public.court_case_definitions(case_id) on delete cascade,
  outcome_key text not null,
  rule_family text not null,
  normalized_inputs text not null,
  deterministic_calculation text not null,
  branch_priority text not null,
  exact_branch_condition text not null,
  fallback_rule text not null,
  result_headline text not null,
  verdict text not null,
  court_ordered_move text not null,
  content_version integer not null default 2,
  updated_at timestamptz not null default now(),
  primary key (case_id, outcome_key)
);
alter table public.court_free_rule_branches enable row level security;
revoke all on public.court_free_rule_branches from public, anon, authenticated;
grant all on public.court_free_rule_branches to service_role;

insert into public.court_case_definitions (
  case_id, category, title, card_subtitle, eligibility, engine, access_tier,
  verdict_method, user_value, question_count, repeatability, sensitivity, status,
  analysis_logic, outcome_keys, scoring_display, result_anatomy,
  insufficient_evidence_rule, notification_copy, content_version
) values
('LOVE-01', 'Love Court', 'WHO''S MORE DOWN BAD?', 'Present the evidence. Your fake chill will be noted.', 'Partner only', 'PLAYFUL_COMPARE', 'plus', 'AI-ASSISTED', 'Compare visible and quiet signs of romantic attachment without ranking love.', 4, 'Monthly', 'Low', 'Launch', 'Award points only for observable attachment behaviors. Compare thought frequency, initiation, memory and effort separately. Never conclude that one person loves more. Use a tie when total scores differ by 0-1; otherwise award a playful behavior-specific crown.', '["balanced","initiator_leads","detail_leads"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for WHO''S MORE DOWN BAD?. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on WHO''S MORE DOWN BAD?.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('LOVE-02', 'Love Court', 'THE ACT-CHILL FRAUD TRIAL', 'One of you is pretending this is all very normal.', 'Partner only', 'PLAYFUL_COMPARE', 'plus', 'AI-ASSISTED', 'Reveal understated affection and emotional softness.', 4, 'Quarterly', 'Low', 'Launch', 'Compare keepsakes, verbal affection and disclosed soft spots. Reward honesty, not emotional intensity. If answers reveal different styles, name both styles rather than selecting a loser.', '["mutual","one_exposed","different_styles"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE ACT-CHILL FRAUD TRIAL. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE ACT-CHILL FRAUD TRIAL.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('LOVE-03', 'Love Court', 'THE FLIRTING LICENSE HEARING', 'Who has game—and who is surviving on eye contact and luck?', 'Partner only', 'PLAYFUL_COMPARE', 'plus', 'AI-ASSISTED', 'Reveal flirting styles and what actually lands.', 4, 'Monthly', 'Low', 'Launch', 'Score initiation and mutual preference fit. Judge the style, not attractiveness. Never shame low initiation. Flag explicit text for partner-only mature handling and do not place it in share copy.', '["mutual_menace","licensed_flirt","style_mismatch"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE FLIRTING LICENSE HEARING. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE FLIRTING LICENSE HEARING.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('LOVE-04', 'Love Court', 'WHO KEEPS STARTING THE CUTE STUFF?', 'Texts, kisses, plans: somebody keeps opening the door.', 'Partner only', 'PLAYFUL_COMPARE', 'free', 'DETERMINISTIC RULES', 'Compare initiation across messages, touch, plans and appreciation.', 4, 'Monthly', 'Low', 'Launch', 'Compare channels and unmet preferences. Do not treat frequency as love. A matched desired channel becomes the Court-Ordered Move; a clear imbalance produces a gentle turn-taking experiment.', '["balanced","imbalance","missed_channel"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for WHO KEEPS STARTING THE CUTE STUFF?. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on WHO KEEPS STARTING THE CUTE STUFF?.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('LOVE-05', 'Love Court', 'THE COMPLIMENT THAT RUINS THEM', 'Find the exact words their brain will replay for three business days.', 'Partner only', 'PREDICT_AND_REVEAL', 'plus', 'AI-ASSISTED', 'Learn what kind of appreciation feels most meaningful.', 4, 'Quarterly', 'Low', 'Launch', 'Compare each self-answer with the other player''s prediction. Weight the open-text semantic match as insight, not score. High match celebrates attunement; mismatch reveals a usable preference without blame.', '["high_match","partial","surprise"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE COMPLIMENT THAT RUINS THEM. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE COMPLIMENT THAT RUINS THEM.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('LOVE-06', 'Love Court', 'YOUR ROM-COM RECEIPTS', 'Two witnesses. One love story. Wildly selective evidence.', 'Partner only', 'MEMORY_COMPARE', 'plus', 'AI-ASSISTED', 'Compare how both people remember meaningful romantic moments.', 4, 'Quarterly', 'Low', 'Launch', 'Use semantic overlap to identify shared memory, complementary detail or different memory. Never mark a person wrong for remembering differently. Do not expose intimate details in social share text.', '["same_memory","different_memory","ordinary_wins"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for YOUR ROM-COM RECEIPTS. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on YOUR ROM-COM RECEIPTS.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('CLOSE-01', 'Closeness Court', 'THE TINY DETAIL TROPHY', 'Let''s see who has actually been paying attention.', 'All relationships', 'PREDICT_AND_REVEAL', 'plus', 'AI-ASSISTED', 'Test awareness of current everyday preferences and context.', 4, 'Monthly', 'Low', 'Launch', 'Compare predictions with self-reports. Score exact category matches and semantic proximity. Reward specific attention; never convert misses into a relationship score.', '["high_match","split","surprise"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE TINY DETAIL TROPHY. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE TINY DETAIL TROPHY.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('CLOSE-02', 'Closeness Court', 'WHO KNOWS WHO BEST?', 'Predict their current settings. Confidence is not evidence.', 'All relationships', 'PREDICT_AND_REVEAL', 'free', 'DETERMINISTIC RULES', 'Test knowledge across preferences, habits and current needs.', 4, 'Monthly', 'Low', 'Launch', 'One point for each exact prediction. Also report the most useful miss. Do not turn the total into closeness, compatibility or relationship health.', '["high","mixed","low"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for WHO KNOWS WHO BEST?. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on WHO KNOWS WHO BEST?.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('CLOSE-03', 'Closeness Court', 'SAME MEMORY, DIFFERENT CAMERA', 'Compare the tiny details each brain quietly kept.', 'All relationships', 'MEMORY_COMPARE', 'plus', 'AI-ASSISTED', 'Reveal shared and complementary memory details.', 4, 'Quarterly', 'Low', 'Launch', 'Compare whether players selected the same memory, then semantic overlap in sequence, detail and meaning. Different memories are valid. Never adjudicate factual disputes involving serious harm.', '["strong_match","complementary","different"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for SAME MEMORY, DIFFERENT CAMERA. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on SAME MEMORY, DIFFERENT CAMERA.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('CLOSE-04', 'Closeness Court', 'WHAT TOOK OVER THEIR BRAIN?', 'Identify the current fixation before it becomes their entire personality.', 'All relationships', 'PREDICT_AND_REVEAL', 'plus', 'AI-ASSISTED', 'Surface current interests without mistaking one activity for a lasting identity.', 4, 'Monthly', 'Low', 'Launch', 'Require the self-report to confirm current interest. Compare type, intensity, next step and semantic topic match. Do not label it a lasting hobby unless continuity is explicit.', '["nailed","topic_only","surprise"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for WHAT TOOK OVER THEIR BRAIN?. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on WHAT TOOK OVER THEIR BRAIN?.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('CLOSE-05', 'Closeness Court', 'READ THE ROOM OR INVENT A STORM?', 'Decode the signal before your brain writes the wrong plot.', 'All relationships', 'PREDICT_AND_REVEAL', 'plus', 'AI-ASSISTED', 'Improve recognition of current mood signals and support preferences.', 4, 'Monthly', 'Medium', 'Launch', 'Compare self-described signal, observer prediction and support preference. Never diagnose mood or infer hidden intent. Focus on preventing one likely misunderstanding.', '["aligned","signal_match","misread"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for READ THE ROOM OR INVENT A STORM?. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on READ THE ROOM OR INVENT A STORM?.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('CLOSE-06', 'Closeness Court', 'BET YOU GET THIS WRONG', 'Predict their tiny choices. The bunny has receipts.', 'All relationships', 'PREDICT_AND_REVEAL', 'free', 'DETERMINISTIC RULES', 'Playfully test current preferences through realistic choices.', 4, 'Weekly', 'Low', 'Launch', 'One point per exact match. Highlight the most actionable matched preference and the funniest miss. Rotate option sets to preserve repeatability.', '["perfect","good","chaos"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for BET YOU GET THIS WRONG. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on BET YOU GET THIS WRONG.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('LIFE-01', 'Life Court', 'THE TAKEOUT TRIBUNAL', 'Nobody wants to decide. Unfortunately, dinner still exists.', 'All relationships; local or remote meal', 'FAIR_DECISION', 'free', 'DETERMINISTIC RULES', 'Choose a meal using appetite, energy, budget and vetoes.', 4, 'Weekly', 'Low', 'Launch', 'Eliminate vetoed options, then maximize craving overlap while respecting the lower budget and lower effort capacity. If no overlap, choose a two-part order or alternating pick.', '["clear","split","low_energy"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE TAKEOUT TRIBUNAL. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE TAKEOUT TRIBUNAL.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('LIFE-02', 'Life Court', 'THE WEEKEND CUSTODY BATTLE', 'Your free time has two lawyers and no clear guardian.', 'All relationships', 'FAIR_DECISION', 'free', 'DETERMINISTIC RULES', 'Balance rest, adventure, chores and social energy.', 4, 'Weekly', 'Low', 'Launch', 'Honor both must-haves, the lower energy level and all hard vetoes. Build one anchor plan plus protected recovery time unless both want more structure.', '["aligned","rest_adventure","productive_cozy"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE WEEKEND CUSTODY BATTLE. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE WEEKEND CUSTODY BATTLE.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('LIFE-03', 'Life Court', 'THE CALL-TIME NEGOTIATION', 'Find a call plan that does not feel like another calendar invite.', 'Long-distance or busy pairs', 'FAIR_DECISION', 'free', 'DETERMINISTIC RULES', 'Choose timing, length and format for the next connection.', 4, 'Weekly', 'Low', 'Launch', 'Find overlapping windows and choose the shorter duration when energy differs. If no live overlap exists, select an asynchronous format. Never imply lower availability means lower care.', '["overlap","format_bridge","energy_gap"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE CALL-TIME NEGOTIATION. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE CALL-TIME NEGOTIATION.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('LIFE-04', 'Life Court', 'THE NEXT-VISIT SURVIVAL PLAN', 'Make the reunion cute without scheduling every breath.', 'Long-distance pairs', 'FAIR_DECISION', 'free', 'DETERMINISTIC RULES', 'Set priorities and divide planning for an upcoming visit.', 4, 'Per visit', 'Medium', 'Launch', 'Build a visit plan around both priorities, the slower preferred pace and explicit disappointment risks. Assign tasks based on volunteered ownership; never infer financial ability.', '["aligned","pace_gap","priority_gap"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE NEXT-VISIT SURVIVAL PLAN. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE NEXT-VISIT SURVIVAL PLAN.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('LIFE-05', 'Life Court', 'THE REMOTE-CONTROL FELONY', 'Two people. One screen. Too many deeply held opinions.', 'All relationships', 'FAIR_DECISION', 'free', 'DETERMINISTIC RULES', 'Choose shared entertainment quickly and fairly.', 4, 'Weekly', 'Low', 'Launch', 'Remove vetoes, match lower attention capacity, then give final selection to the person who did not pick last. If fairness is unknown, offer a three-option shortlist.', '["clear","picker","attention_gap"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE REMOTE-CONTROL FELONY. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE REMOTE-CONTROL FELONY.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('LIFE-06', 'Life Court', 'WHO PLANS THE NEXT THING?', 'The clipboard is in evidence. Someone is leaving with it.', 'All relationships', 'FAIR_DECISION', 'free', 'DETERMINISTIC RULES', 'Distribute planning responsibility for the next shared activity.', 4, 'Monthly', 'Low', 'Launch', 'Prioritize fairness history and current capacity. Assign discrete roles from volunteered ownership. Never punish the lower-energy person; use a lighter role or future turn.', '["clear_owner","split_roles","low_capacity"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for WHO PLANS THE NEXT THING?. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on WHO PLANS THE NEXT THING?.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('MIDDLE-01', 'Meet in the Middle', 'THE ''WHY AREN''T THEY REPLYING?'' CASE', 'One unread message. Seventeen imaginary explanations.', 'All relationships', 'COMMON_GROUND', 'free', 'DETERMINISTIC RULES', 'Align response expectations without measuring care by speed.', 4, 'As needed', 'Medium', 'Launch', 'Identify each comfort window, reasons and smallest realistic reassurance. Never interpret slow replies as avoidance or lack of care. Output the smallest mutual rule both explicitly support.', '["aligned","bridge","no_overlap"]'::jsonb, 'No score shown', 'What You Need + What They Need + Where You Meet + Try This', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A little middle ground?","inviteBody":"Your person invited you to work through the ''why aren''t they replying?'' case together.","inviteCta":"Add Your Side","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE ''WHY AREN''T THEY REPLYING?'' CASE.","readyCta":"Hear the Verdict","privacyNote":"No pressure to agree instantly. Start with your honest side."}'::jsonb, 2),
('MIDDLE-02', 'Meet in the Middle', 'TALK NOW OR MAKE IT WEIRDER?', 'Choose a pause that cools things down without becoming a disappearance.', 'All relationships', 'COMMON_GROUND', 'free', 'DETERMINISTIC RULES', 'Agree on conflict timing and safe cooling-off signals.', 4, 'As needed', 'Medium', 'Launch', 'Use the longer minimum pause required for regulation, but require a return signal within the shorter person''s safety window. Do not mediate threats, abuse or coercion; route those cases out.', '["aligned","pace_gap","too_hot"]'::jsonb, 'No score shown', 'What You Need + What They Need + Where You Meet + Try This', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A little middle ground?","inviteBody":"Your person invited you to work through talk now or make it weirder? together.","inviteCta":"Add Your Side","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on TALK NOW OR MAKE IT WEIRDER?.","readyCta":"Hear the Verdict","privacyNote":"No pressure to agree instantly. Start with your honest side."}'::jsonb, 2),
('MIDDLE-03', 'Meet in the Middle', 'FIX IT OR JUST HEAR ME?', 'One bad day can survive. Unlicensed life coaching may not.', 'All relationships', 'COMMON_GROUND', 'free', 'DETERMINISTIC RULES', 'Align support style during stress.', 4, 'Monthly or as needed', 'Medium', 'Launch', 'Compare preferred first response and avoid list. Produce an explicit two-option check-in when preferences differ. Never assume advice is welcome.', '["aligned","fixer_listener","different_days"]'::jsonb, 'No score shown', 'What You Need + What They Need + Where You Meet + Try This', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A little middle ground?","inviteBody":"Your person invited you to work through fix it or just hear me? together.","inviteCta":"Add Your Side","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on FIX IT OR JUST HEAR ME?.","readyCta":"Hear the Verdict","privacyNote":"No pressure to agree instantly. Start with your honest side."}'::jsonb, 2),
('MIDDLE-04', 'Meet in the Middle', 'SPACE WITHOUT THE SPIRAL', 'Define breathing room before somebody mistakes it for goodbye.', 'All relationships', 'COMMON_GROUND', 'free', 'DETERMINISTIC RULES', 'Balance alone time with relational reassurance.', 4, 'As needed', 'Medium', 'Launch', 'Respect the longer stated space need while adding only the minimum reassurance and return point selected by both. Reject punitive silence, monitoring and coercive demands.', '["aligned","bridge","unclear"]'::jsonb, 'No score shown', 'What You Need + What They Need + Where You Meet + Try This', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A little middle ground?","inviteBody":"Your person invited you to work through space without the spiral together.","inviteCta":"Add Your Side","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on SPACE WITHOUT THE SPIRAL.","readyCta":"Hear the Verdict","privacyNote":"No pressure to agree instantly. Start with your honest side."}'::jsonb, 2),
('MIDDLE-05', 'Meet in the Middle', 'ARE WE TOGETHER OR JUST NEARBY?', 'Put quality time on trial. Multitasking has been subpoenaed.', 'All relationships', 'COMMON_GROUND', 'free', 'DETERMINISTIC RULES', 'Define a realistic shared ritual that feels meaningful to both.', 4, 'Monthly', 'Medium', 'Launch', 'Choose a ritual both accept, within the lower capacity, and remove the highest-overlap blocker. Never frame quantity as proof of care.', '["aligned","type_gap","capacity_gap"]'::jsonb, 'No score shown', 'What You Need + What They Need + Where You Meet + Try This', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A little middle ground?","inviteBody":"Your person invited you to work through are we together or just nearby? together.","inviteCta":"Add Your Side","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on ARE WE TOGETHER OR JUST NEARBY?.","readyCta":"Hear the Verdict","privacyNote":"No pressure to agree instantly. Start with your honest side."}'::jsonb, 2),
('MIDDLE-06', 'Meet in the Middle', 'THE SOCIAL-BATTERY APPEAL', 'One wants people. One wants silence. Nobody has to become the villain.', 'All relationships', 'COMMON_GROUND', 'free', 'DETERMINISTIC RULES', 'Balance social activity, companionship and recovery.', 4, 'As needed', 'Low-Medium', 'Launch', 'Use the lower social battery as the capacity limit. Prefer a compromise explicitly accepted by both; otherwise allow separate plans without moral judgment.', '["aligned","bridge","short_plan"]'::jsonb, 'No score shown', 'What You Need + What They Need + Where You Meet + Try This', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A little middle ground?","inviteBody":"Your person invited you to work through the social-battery appeal together.","inviteCta":"Add Your Side","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE SOCIAL-BATTERY APPEAL.","readyCta":"Hear the Verdict","privacyNote":"No pressure to agree instantly. Start with your honest side."}'::jsonb, 2),
('LOVE-F01', 'Love Court', 'THE TINY LOVE RECEIPTS', 'Grand gestures may sit down. The microscopic evidence is speaking.', 'Partner only', 'RULE_MATCH', 'free', 'DETERMINISTIC RULES', 'Match the affection each person naturally gives with what the other most notices.', 3, 'Monthly', 'Low', 'Free Launch', 'Compare A.give_style with B.receive_style and B.give_style with A.receive_style. Two matches = double_match; one match = one_match; zero matches = reroute. Court-Ordered Move uses each person’s available_move only when it matches the other person’s receive_style; otherwise use the closest selected receive style.', '["double_match","one_match","reroute"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE TINY LOVE RECEIPTS. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE TINY LOVE RECEIPTS.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('LOVE-F02', 'Love Court', 'THE YEARNING LEAK', 'You tried to act normal. Unfortunately, your behavior testified.', 'Partner only', 'RULE_MATCH', 'free', 'DETERMINISTIC RULES', 'Reveal each person’s low-pressure missing-you signal and preferred response.', 3, 'Monthly', 'Low', 'Free Launch', 'Compare each sent_signal with the other’s wanted_signal. Exact reciprocal matches = same_frequency; one compatible signal = quiet_match; no compatible signal = hidden_signal. Contact rhythm agreement refines the move but never becomes a closeness score.', '["same_frequency","quiet_match","hidden_signal"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE YEARNING LEAK. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE YEARNING LEAK.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('LOVE-F03', 'Love Court', 'ROMANCE VS. THE BATTERY', 'Design a date your energy, wallet, and remaining brain cell can survive.', 'Partner only', 'RULE_RECIPE', 'free', 'DETERMINISTIC RULES', 'Create a realistic date format from shared energy, budget and planning preferences.', 3, 'Weekly', 'Low', 'Free Launch', 'Use the lower shared budget ceiling, the lower shared energy level unless one selects surprise and the other can plan, and the highest available planning capacity. Output home_date, tiny_adventure or proper_date. Never recommend spending above either person’s selection.', '["home_date","tiny_adventure","proper_date"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for ROMANCE VS. THE BATTERY. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on ROMANCE VS. THE BATTERY.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('CLOSE-F01', 'Closeness Court', 'THE BAD-DAY CHEAT CODE', 'One cursed day. Five possible moves. Please don''t deploy a speech.', 'All relationships', 'RULE_MATCH', 'free', 'DETERMINISTIC RULES', 'Match a person’s bad-day need with a response the other can confidently use.', 3, 'Monthly', 'Low-Medium', 'Free Launch', 'Pair each first_need with its fixed response template, block the selected avoid style, and apply reply_load. Same first_need = shared_manual; different but nonconflicting needs = two_manuals; either selects space or no_reply = soft_mode.', '["shared_manual","two_manuals","soft_mode"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE BAD-DAY CHEAT CODE. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE BAD-DAY CHEAT CODE.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('CLOSE-F02', 'Closeness Court', 'THE LITTLE-THING RADAR', 'What is carrying them—and what is quietly eating their battery?', 'All relationships', 'PREDICT_SCORE', 'free', 'DETERMINISTIC RULES', 'Test current everyday knowledge without turning misses into a relationship score.', 3, 'Weekly', 'Low', 'Free Launch', 'Score exact prediction matches across three dimensions. Three matches = radar_locked; one or two = signal_found; zero = fresh_lore. Never display a percentage, grade or relationship score. The result surfaces the most useful mismatch as a new detail.', '["radar_locked","signal_found","fresh_lore"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE LITTLE-THING RADAR. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE LITTLE-THING RADAR.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('CLOSE-F03', 'Closeness Court', 'THE QUIET CARE SETTINGS', 'For when the love is present but the social battery is deceased.', 'All relationships', 'RULE_MATCH', 'free', 'DETERMINISTIC RULES', 'Find a mutually comfortable low-energy contact style.', 3, 'Monthly', 'Low', 'Free Launch', 'Match available_signal to the other person’s wanted_signal. Two matches = quiet_sync; one = one_easy_bridge; none or a selected none/warm_space pair = space_with_warmth. Return window becomes the fixed follow-up rule.', '["quiet_sync","one_easy_bridge","space_with_warmth"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE QUIET CARE SETTINGS. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE QUIET CARE SETTINGS.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('LIFE-F01', 'Life Court', 'THE 3% BATTERY PLAN', 'Tonight has no executive function. Pick one realistic form of togetherness.', 'All relationships', 'RULE_RECIPE', 'free', 'DETERMINISTIC RULES', 'Turn current energy and availability into one realistic shared plan.', 3, 'Daily', 'Low', 'Free Launch', 'Use the lower battery level as the time ceiling, choose an overlapping location/channel, and apply the selected benefit. Output tiny_touchpoint, shared_reset or solo_reset. Never assign a call when either selects solo or text only.', '["tiny_touchpoint","shared_reset","solo_reset"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE 3% BATTERY PLAN. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE 3% BATTERY PLAN.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('LIFE-F02', 'Life Court', 'THE MICRO-DATE GENERATOR', 'Romance, but sized for your actual schedule and nervous system.', 'Partners or close pairs who want shared time', 'RULE_RECIPE', 'free', 'DETERMINISTIC RULES', 'Generate a low-friction shared activity from time, setting and mood.', 3, 'Weekly', 'Low', 'Free Launch', 'Cross time, compatible habitat and vibe through a fixed activity matrix. If habitats do not overlap, use remote. If either time is 10 minutes, cap at 10. Output remote_microdate, quick_outing or slow_evening.', '["remote_microdate","quick_outing","slow_evening"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE MICRO-DATE GENERATOR. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE MICRO-DATE GENERATOR.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('LIFE-F03', 'Life Court', 'THE CHORE DRAFT', 'Divide the boring stuff before one of you starts building a legal case.', 'Pairs who share a home or recurring chores', 'RULE_ASSIGN', 'free', 'DETERMINISTIC RULES', 'Assign one low-stakes chore fairly using dislike, capacity and recent turn-taking.', 3, 'Weekly', 'Low', 'Free Launch', 'Never assign a person’s top-hated chore when the other lists it as tolerable. Weight recent workload: if both agree one carried more, give that person first pick; if disputed or unknown, rotate. Output clean_swap, first_pick or rotation.', '["clean_swap","first_pick","rotation"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE CHORE DRAFT. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE CHORE DRAFT.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb, 2),
('MIDDLE-F01', 'Meet in the Middle', 'THE CHECK-IN SETTINGS', 'Enough contact to feel close. Not enough to become homework.', 'All relationships', 'RULE_OVERLAP', 'free', 'DETERMINISTIC RULES', 'Find a sustainable check-in rhythm and channel without pressure.', 3, 'Monthly', 'Low', 'Free Launch', 'Choose the lower-frequency preference, the lowest-effort overlapping channel, and each person’s acceptable busy signal. Output same_settings, light_bridge or custom_settings. Never frame lower contact as lower care.', '["same_settings","light_bridge","custom_settings"]'::jsonb, 'No score shown', 'What You Need + What They Need + Where You Meet + Try This', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A little middle ground?","inviteBody":"Your person invited you to work through the check-in settings together.","inviteCta":"Add Your Side","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE CHECK-IN SETTINGS.","readyCta":"Hear the Verdict","privacyNote":"No pressure to agree instantly. Start with your honest side."}'::jsonb, 2),
('MIDDLE-F02', 'Meet in the Middle', 'THE CANCELLED-PLAN REPAIR KIT', 'Plans changed. Now decide what would stop the emotional property damage.', 'All relationships', 'RULE_PROTOCOL', 'free', 'DETERMINISTIC RULES', 'Create a fair low-stakes rescheduling protocol from notice, context and repair preferences.', 3, 'As needed', 'Low-Medium', 'Free Launch', 'Build a fixed protocol using the stricter notice preference, each person’s sting trigger and selected repair. Same repair = shared_protocol; compatible repairs = two_step; conflicting capacity = minimum_viable_repair. Never decide whether a cancellation was morally justified.', '["shared_protocol","two_step","minimum_viable_repair"]'::jsonb, 'No score shown', 'What You Need + What They Need + Where You Meet + Try This', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A little middle ground?","inviteBody":"Your person invited you to work through the cancelled-plan repair kit together.","inviteCta":"Add Your Side","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE CANCELLED-PLAN REPAIR KIT.","readyCta":"Hear the Verdict","privacyNote":"No pressure to agree instantly. Start with your honest side."}'::jsonb, 2),
('MIDDLE-F03', 'Meet in the Middle', 'THE PHONE-DOWN TREATY', 'Settle when the screen is useful—and when it is absolutely third-wheeling.', 'All relationships', 'RULE_PROTOCOL', 'free', 'DETERMINISTIC RULES', 'Agree on a realistic phone boundary for shared time without policing each other.', 3, 'Monthly', 'Low', 'Free Launch', 'Select the narrowest shared trigger, union nonconflicting exceptions, and choose an exact matching boundary when available. Otherwise choose the least restrictive boundary that addresses both triggers. Output exact_treaty, tiny_boundary or awareness_only.', '["exact_treaty","tiny_boundary","awareness_only"]'::jsonb, 'No score shown', 'What You Need + What They Need + Where You Meet + Try This', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A little middle ground?","inviteBody":"Your person invited you to work through the phone-down treaty together.","inviteCta":"Add Your Side","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE PHONE-DOWN TREATY.","readyCta":"Hear the Verdict","privacyNote":"No pressure to agree instantly. Start with your honest side."}'::jsonb, 2)
