insert into public.court_verdict_templates (
  case_id, outcome_key, headline, what_court_heard, verdict, court_ordered_move, share_text, tone_condition
) values
('LOVE-01', 'balanced', 'A DISTURBINGLY CLOSE TIE', 'You both kept finding each other in the middle of ordinary moments.', 'No winner. Just two people pretending to be normal about each other.', 'Each send one ''this reminded me of you'' moment today.', 'Bunny Court found us equally guilty of being down bad.', 'Warm and playful; remove humor if submitted content raises emotional weight.'),
('LOVE-01', 'initiator_leads', 'THE AFFECTION DEPARTMENT HAS A LEAD', 'One of you starts more of the texts, plans and obvious affection. The other keeps more quiet reminders.', 'Different evidence, same attachment. One is louder; one leaves a paper trail.', 'Trade styles once today: the quiet one initiates, the initiator sends a small memory.', 'The court exposed our two completely different ways of being down bad.', 'Warm and playful; remove humor if submitted content raises emotional weight.'),
('LOVE-01', 'detail_leads', 'THE DETAIL DETECTIVE TAKES IT', 'One of you remembered more tiny details while the other showed up through action.', 'The crown goes to the detail keeper. The effort charge remains mutual.', 'Send them one detail you noticed but never mentioned.', 'Apparently remembering their exact coffee order counts as legal evidence.', 'Warm and playful; remove humor if submitted content raises emotional weight.'),
('LOVE-02', 'mutual', 'TWO SOFTIES IN A TRENCH COAT', 'Both of you admitted to keeping more emotional evidence than expected.', 'The chill act has been dismissed for lack of credibility.', 'Reveal one saved message or tiny reminder to each other.', 'We both lost the Secret Softie case. Devastating.', 'Warm and playful; remove humor if submitted content raises emotional weight.'),
('LOVE-02', 'one_exposed', 'THE SECRET SOFTIE HAS BEEN IDENTIFIED', 'One of you keeps the receipts, remembers the details and feels more than they publicly admit.', 'The court recognizes one certified softie and one delighted beneficiary.', 'The certified softie chooses tonight''s tiny affectionate ritual.', 'Bunny Court exposed the soft one in our relationship.', 'Warm and playful; remove humor if submitted content raises emotional weight.'),
('LOVE-02', 'different_styles', 'SOFT, JUST IN DIFFERENT FONTS', 'One of you says it. The other saves it, remembers it or quietly makes room for it.', 'No contradiction found. Affection simply has two accents here.', 'Each show affection once in the other person''s preferred style.', 'Same softness. Completely different fonts.', 'Warm and playful; remove humor if submitted content raises emotional weight.'),
('LOVE-03', 'mutual_menace', 'MUTUAL MENACE CONFIRMED', 'Your preferred flirting styles line up almost suspiciously well.', 'The court advises the public to give you two some space.', 'Use the winning line on your person today.', 'Bunny Court confirmed our flirting is a community risk.', 'Warm and playful; remove humor if submitted content raises emotional weight.'),
('LOVE-03', 'licensed_flirt', 'ONE LICENSED FLIRT. ONE EASY TARGET.', 'One person initiates more; the other is extremely receptive to the exact style being used.', 'This system is unfair but undeniably functional.', 'The quieter player sends the next flirty message first.', 'Our flirting ecosystem has been legally documented.', 'Warm and playful; remove humor if submitted content raises emotional weight.'),
('LOVE-03', 'style_mismatch', 'GOOD INTENTIONS. WRONG DELIVERY.', 'You both flirt, but the style being sent is not always the style that lands.', 'No chemistry issue found. The subtitles were simply off.', 'Try one flirt in the style your person selected.', 'Turns out we had flirting. We just needed subtitles.', 'Warm and playful; remove humor if submitted content raises emotional weight.'),
('LOVE-04', 'balanced', 'AFFECTION IS CLOCKING IN ON BOTH SHIFTS', 'You initiate different things, and together they cover more ground than either of you noticed.', 'The department is functioning. Morale is suspiciously cute.', 'Thank each other for one kind of initiation you usually overlook.', 'Our affection department passed inspection.', 'Warm and playful; remove humor if submitted content raises emotional weight.'),
('LOVE-04', 'imbalance', 'ONE PERSON HAS BEEN CARRYING THE CLIPBOARD', 'One of you starts more connection across several channels. The other wants to contribute but hits a clear barrier.', 'This is a handoff problem, not a love problem.', 'The quieter initiator chooses and starts one easy action this week.', 'Bunny Court assigned a new shift in our affection department.', 'Warm and playful; remove humor if submitted content raises emotional weight.'),
('LOVE-04', 'missed_channel', 'RIGHT LOVE. WRONG DOORBELL.', 'Affection is being initiated, but not always in the form the other person notices most.', 'Effort is present. Delivery needs rerouting.', 'Use the exact channel your person selected once this week.', 'The love was there. We were ringing the wrong doorbell.', 'Warm and playful; remove humor if submitted content raises emotional weight.'),
('LOVE-05', 'high_match', 'THE COMPLIMENT TRANSLATOR IS WORKING', 'You correctly recognized both what they want noticed and how they like to hear it.', 'Your compliments are cleared for emotional landing.', 'Send the unsaid compliment in their preferred style.', 'Bunny Court says I know exactly which compliment gets through.', 'Warm and playful; remove humor if submitted content raises emotional weight.'),
('LOVE-05', 'partial', 'YOU KNOW THE MESSAGE, NOT THE PACKAGING', 'You understand what they value, but their preferred timing or delivery surprised you.', 'The words were good. The envelope needed work.', 'Repeat one familiar compliment with the delivery they chose.', 'We had the right compliment in the wrong packaging.', 'Warm and playful; remove humor if submitted content raises emotional weight.'),
('LOVE-05', 'surprise', 'NEW INFORMATION HAS ENTERED THE CHAT', 'Their most meaningful compliment was not the one you predicted.', 'No failure here. You just received highly actionable evidence.', 'Use their selected compliment type once in the next seven days.', 'Bunny Court just upgraded my compliment settings.', 'Warm and playful; remove humor if submitted content raises emotional weight.'),
('LOVE-06', 'same_memory', 'SAME MEMORY. DIFFERENT CAMERA ANGLES.', 'You chose the same chapter, but each kept a different tiny detail from it.', 'The memory matches. The director''s cuts are beautifully different.', 'Tell each other the detail you never knew they remembered.', 'We remembered the same love story from two different camera angles.', 'Warm and playful; remove humor if submitted content raises emotional weight.'),
('LOVE-06', 'different_memory', 'TWO MOMENTS MADE THE CASE', 'You chose different memories, and both reveal what closeness looked like to you.', 'The relationship has more than one origin story. The court allows it.', 'Recreate one small detail from each memory.', 'Bunny Court found two completely different favorite chapters.', 'Warm and playful; remove humor if submitted content raises emotional weight.'),
